const $=s=>document.querySelector(s);let lang='en',view='overview',tab='lighting',library='themes',port=0,notice='';
const defaults=()=>({color:'#ad85ff',brightness:75,effect:'Static',cooling:'Balanced',theme:'Focus',label:'CPU',sensor:true});
const drafts={fans:defaults(),pump:defaults()},saved=structuredClone(drafts);const t=(en,ru)=>lang==='en'?en:ru;
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true">${name==='grid'?'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>':'<rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/>'}</svg>`;
function fans(color='#ad85ff'){return `<svg viewBox="0 0 440 160" role="img" aria-label="${t('Three fan zones, schematic','Схема трёх вентиляторов')}">${[0,1,2].map(i=>`<g transform="translate(${i*145+7},12)"><rect width="134" height="134" rx="12" fill="#1d2029" stroke="#494b58"/><rect x="7" y="7" width="120" height="120" rx="9" fill="none" stroke="${color}" stroke-width="3"/><circle cx="67" cy="67" r="48" fill="#10131b" stroke="${color}" stroke-width="3"/>${[0,60,120,180,240,300].map(a=>`<path d="M67 67 Q42 25 78 25 Q99 31 76 63Z" fill="#313443" transform="rotate(${a} 67 67)"/>`).join('')}<circle cx="67" cy="67" r="15" fill="#1e2230" stroke="#797585"/><path d="M61 64h12m-12 6h8" stroke="${color}"/></g>`).join('')}</svg>`}
function pump(color='#ad85ff'){return `<svg viewBox="0 0 400 190" role="img" aria-label="${t('Pump display, schematic','Схема экрана помпы')}"><path d="M258 62H360M258 88H360" stroke="#343744" stroke-width="16"/><rect x="122" y="19" width="150" height="150" rx="28" fill="#232631" stroke="#56596a"/><rect x="137" y="34" width="120" height="120" fill="#0c1018" stroke="${color}" stroke-width="3"/><text x="197" y="99" text-anchor="middle" fill="${color}" font-size="37" font-family="sans-serif">42°</text><text x="197" y="122" text-anchor="middle" fill="#b3b9c9" font-size="10">CPU</text></svg>`}
const name=()=>view==='fans'?'SL-INFINITY':'GALAHAD II';
function nav(){return `<aside><div class="brand">L<span>·</span>CONNECT<small>LINUX</small></div><div class="nav"><button data-view="overview" class="${view==='overview'?'selected':''}">${icon('grid')}${t('Overview','Обзор')}</button></div><div><p class="nav-label">${t('YOUR DEVICES','ВАШИ УСТРОЙСТВА')}</p><div class="nav device-nav"><button data-view="fans" class="${view==='fans'?'selected':''}">${icon('fan')}<span>SL-INFINITY<small>${t('Fan controller','Контроллер вентиляторов')}</small></span></button><button data-view="pump" class="${view==='pump'?'selected':''}">${icon('fan')}<span>GALAHAD II<small>LCDV2</small></span></button></div></div><div class="side-bottom"><label>${t('Language','Язык')}<select id="language"><option value="en" ${lang==='en'?'selected':''}>EN</option><option value="ru" ${lang==='ru'?'selected':''}>RU</option></select></label><p class="demo">${t('Interactive concept. Demo devices and readings. No hardware connection.','Интерактивный концепт. Примерные устройства и показания. Без подключения к оборудованию.')}</p></div></aside>`}
function overview(){return `<div class="heading"><div><h1>${t('Your setup. Your signature.','Твой ПК. Твой стиль.')}</h1><p class="muted">${t('A little light. A quieter system. Make it yours.','Добавь света. Настрой тишину. Сделай по-своему.')}</p></div></div><div class="devices">${['fans','pump'].map((d,i)=>`<article class="device-row"><div class="hardware">${i?pump(drafts[d].color):fans(drafts[d].color)}</div><div class="device-info"><h2>${i?'GALAHAD II LCDV2':'UNI FAN SL-INFINITY'}</h2><p class="muted">${i?t('A personal touch, right at the heart of your build.','Твой стиль — в самом сердце компьютера.'):t('Three fans. One coordinated look.','Три вентилятора. Единое оформление.')}</p><div class="caps"><button data-open="${d}" data-tab="lighting">${t('Lighting','Подсветка')}</button><button data-open="${d}" data-tab="cooling">${t('Cooling','Охлаждение')}</button>${i?`<button data-open="pump" data-tab="display">${t('LCD screen','Экран LCD')}</button>`:''}</div></div></article>`).join('')}</div><div class="overview-foot"><p>${t('Two example device families · features vary by device','Два примера семейств устройств · возможности зависят от модели')}</p><p>${t('SL-INFINITY is a design example, not supported hardware in this build.','SL-INFINITY — пример дизайна, не поддерживаемое в этой сборке устройство.')}</p></div>`}
function studio(){const d=drafts[view];const dirty=JSON.stringify(d)!==JSON.stringify(saved[view]);return `<div class="heading"><div><h1>${name()} ${view==='pump'?'<span class="muted">LCDV2</span>':''}</h1><p class="muted">${view==='fans'?t('Fan controller · 3 fans on Port 1 · demo','Контроллер · 3 вентилятора на порту 1 · демо'):t('Liquid cooler · demo device','Система охлаждения · демонстрационное устройство')}</p></div><button class="outline" data-view="overview">${t('All devices','Все устройства')}</button></div><div class="tabs">${['lighting','cooling',...(view==='pump'?['display']:[])].map(x=>`<button data-tab="${x}" class="${tab===x?'active':''}" aria-pressed="${tab===x}">${({lighting:t('Lighting','Подсветка'),cooling:t('Cooling','Охлаждение'),display:t('LCD screen','Экран LCD')})[x]}</button>`).join('')}</div><div class="studio reveal"><div>${stage(d)}${tab==='display'?libraryUI(d):''}</div><section class="inspector" aria-label="${t('Device settings','Настройки устройства')}">${controls(d)}</section></div><div class="applybar"><div role="status" aria-live="polite"><strong class="${dirty?'changed':notice?'toast':''}">${dirty?t('Unapplied changes','Есть неприменённые изменения'):notice||t('You’re up to date','Изменений нет')}</strong><span class="muted">${t('Preview only. Apply saves this demo state locally in the current session.','Предпросмотр. Применение сохраняет демосостояние в текущем сеансе.')}</span></div><div><button id="revert" ${dirty?'':'disabled'}>${t('Revert','Отменить')}</button><button id="apply" class="primary" ${dirty?'':'disabled'}>${t('Apply changes','Применить')}</button></div></div>`}
function stage(d){if(tab==='display')return `<div class="stage"><div class="lcd ${d.theme==='Orbit'?'line':d.theme==='Clock'?'clock':''}" style="--light:${d.color}"><small>${d.theme==='Clock'?t('FRIDAY, OCTOBER 16','ПЯТНИЦА, 16 ОКТЯБРЯ'):escapeHTML(d.label)}</small><strong>${d.theme==='Clock'?'21:48':d.sensor?'42°':'—'}</strong><small>${d.theme==='Clock'?t('MAKE TIME YOURS','ВРЕМЯ ДЛЯ СЕБЯ'):t('DEMO READING','ПРИМЕР ПОКАЗАНИЯ')}</small></div><p class="stage-caption">${t('LCD preview · 480 × 480','Предпросмотр LCD · 480 × 480')}</p></div>`;
if(tab==='cooling'){let y=d.cooling==='Quiet'?135:d.cooling==='Balanced'?100:65;return `<div class="stage"><svg class="curve" viewBox="0 0 500 250" role="img" aria-label="${t('Illustrative fan curve','Иллюстративная кривая охлаждения')}">${[50,100,150,200].map((v,i)=>`<path d="M45 ${v}H475" stroke="#343743"/><text x="8" y="${v+4}" class="zone-label">${100-i*25}%</text>`).join('')}<path d="M45 195L150 180L260 ${y}L365 70L475 50" fill="none" stroke="#b9a7ff" stroke-width="3"/>${[[45,195],[150,180],[260,y],[365,70],[475,50]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5" fill="#d7cbff"/>`).join('')}<text x="45" y="235" class="zone-label">30°C</text><text x="250" y="235" class="zone-label">60°C</text><text x="440" y="235" class="zone-label">90°C</text></svg><p class="stage-caption">${t('Example curve · not calibrated for hardware','Пример кривой · не откалиброван для оборудования')}</p></div>`}
return `<div class="stage"><div style="width:100%;opacity:${.25+d.brightness/100*.75}">${view==='fans'?fans(d.color):pump(d.color)}</div><p class="stage-caption">${view==='fans'?t('Port 1 · 3 fans · lighting schematic','Порт 1 · 3 вентилятора · схема подсветки'):t('Lighting schematic · selected device','Схема подсветки выбранного устройства')}</p></div>`}
function controls(d){if(tab==='cooling')return `<h3>${t('Cooling profile','Профиль охлаждения')}</h3><div class="field"><span>${t('Choose your balance','Выбери свой баланс')}</span><div class="segments">${['Quiet','Balanced','Performance'].map((p,i)=>`<button data-cooling="${p}" class="${d.cooling===p?'active':''}">${lang==='en'?p:['Тихий','Баланс','Мощный'][i]}</button>`).join('')}</div></div><p class="helper">${t('The curve updates with your profile. Manual curve editing is outside this concept.','Кривая меняется вместе с профилем. Ручной редактор кривой не входит в этот концепт.')}</p>`;
if(tab==='display' && d.theme==='Clock')return `<h3>${t('Clock appearance','Оформление часов')}</h3>${colors(d)}<p class="helper">${t('This theme shows time and date. Sensor controls are available in Focus and Orbit.','Эта тема показывает время и дату. Настройки датчика доступны в Focus и Orbit.')}</p>`;
if(tab==='display')return `<h3>${t('Make it yours','Настрой под себя')}</h3><div class="field"><label for="label">${t('Sensor label','Подпись датчика')}</label><input type="text" id="label" maxlength="24" value="${escapeHTML(d.label)}"></div><div class="field"><label><input id="sensor" type="checkbox" ${d.sensor?'checked':''}> ${t('Show sample temperature','Показывать пример температуры')}</label></div>${colors(d)}<p class="helper">${t('Choose a theme below the preview, or switch to Layers to adjust its content.','Выбери тему под предпросмотром или открой слои, чтобы изменить содержимое.')}</p>`;
return `<h3>${t('Lighting settings','Настройки подсветки')}</h3>${view==='fans'?`<div class="field"><span>${t('Fan group','Группа вентиляторов')}</span><div class="segments"><button class="active">${t('Port 1 · 3 fans','Порт 1 · 3 вентилятора')}</button></div><small>${t('Other ports are empty in this example.','Остальные порты в этом примере пусты.')}</small></div>`:''}<div class="field"><label for="effect">${t('Effect','Эффект')}</label><select id="effect">${['Static','Breathing'].map((x,i)=>`<option ${d.effect===x?'selected':''} value="${x}">${lang==='en'?x:['Статичный','Дыхание'][i]}</option>`).join('')}</select></div>${colors(d)}<div class="field"><div class="field-head"><label for="brightness">${t('Brightness','Яркость')}</label><output>${d.brightness}%</output></div><input id="brightness" type="range" min="0" max="100" value="${d.brightness}"></div><p class="helper">${t('Schematic color preview. Animation timing is not simulated.','Схема показывает цвет. Время и ритм анимации не моделируются.')}</p>`}
function colors(d){return `<div class="field"><span>${t('Accent color','Цвет')}</span><div class="swatches">${['#ad85ff','#64dccc','#eaa174','#ededf5'].map((c,i)=>`<button class="swatch ${d.color===c?'active':''}" data-color="${c}" style="--swatch:${c}" aria-label="${[t('Violet','Фиолетовый'),t('Mint','Мятный'),t('Amber','Янтарный'),t('White','Белый')][i]}"></button>`).join('')}<input type="color" id="color" value="${d.color}" aria-label="${t('Custom color','Другой цвет')}"></div></div>`}
function libraryUI(d){return `<section class="library"><div class="library-head"><div class="segments"><button data-library="themes" class="${library==='themes'?'active':''}">${t('Themes','Темы')}</button><button data-library="layers" class="${library==='layers'?'active':''}">${t('Layers','Слои')}</button></div><small>${t('Local examples','Локальные примеры')}</small></div>${library==='themes'?`<div class="themes">${['Focus','Orbit','Clock'].map((x,i)=>`<button data-theme="${x}" class="theme ${d.theme===x?'active':''}"><div class="theme-art">${['42°','◯','21:48'][i]}</div>${x}<br><small>${[t('Sensor','Датчик'),t('Atmosphere','Атмосфера'),t('Time','Время')][i]}</small></button>`).join('')}</div>`:`<div class="layers">${d.theme==='Clock'?`<p class="helper">${t('Time and date · color is editable in the inspector.','Время и дата · цвет меняется в панели настроек.')}</p>`:`<div class="layer"><span>${t('Temperature','Температура')}</span><label><input type="checkbox" id="layerSensor" ${d.sensor?'checked':''}> ${t('Visible','Видимый')}</label></div><div class="layer"><span>${t('Label','Подпись')}</span><span>${escapeHTML(d.label)}</span></div><p class="helper">${t('Edit the label and color in the inspector.','Подпись и цвет меняются в панели настроек.')}</p>`}</div>`}</section>`}
function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){const active=document.activeElement;const focusId=active?.id;const focusData=active?.dataset?Object.entries(active.dataset):[];document.documentElement.lang=lang;$('#app').innerHTML=`<div class="shell">${nav()}<main class="main"><div class="topline"><span>${t('Device studio','Студия устройств')}</span><span class="badge"><span class="dot"></span>${t('Design preview · simulated data','Прототип дизайна · демонстрационные данные')}</span></div>${view==='overview'?overview():studio()}</main></div>`;bind();if(focusId)document.getElementById(focusId)?.focus();else if(focusData.length){const [k,v]=focusData[0];document.querySelectorAll('button').forEach(b=>{if(b.dataset[k]===v)b.focus({preventScroll:true})})}}
function change(key,val){drafts[view][key]=val;notice='';render()}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;tab='lighting';notice='';render()});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{view=b.dataset.open;tab=b.dataset.tab;notice='';render()});document.querySelectorAll('.tabs [data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});['color','cooling','theme','library'].forEach(k=>document.querySelectorAll(`[data-${k}]`).forEach(b=>b.onclick=()=>{if(k==='library'){library=b.dataset[k];render()}else change(k,b.dataset[k])}));$('#language').onchange=e=>{lang=e.target.value;notice='';render()};['effect','color','brightness','label','sensor','layerSensor'].forEach(k=>{const el=$('#'+k);if(el)el.onchange=e=>change(k==='layerSensor'?'sensor':k,k==='brightness'?Number(e.target.value):['sensor','layerSensor'].includes(k)?e.target.checked:e.target.value)});if($('#apply'))$('#apply').onclick=()=>{saved[view]=structuredClone(drafts[view]);notice=t('Applied to demo','Применено в демо');render()};if($('#revert'))$('#revert').onclick=()=>{drafts[view]=structuredClone(saved[view]);notice='';render()}}
render();
